  if(!eligible.length)throw Error('시작 성계 후보가 없습니다.');
  const home=eligible[Math.floor(rand()*eligible.length)];
  // 시작 성계를 0번 ID로 재배치하여 기존 탐험/함선 시스템과 호환한다.
